export const UI_PHRASEBOOKS = Object.fromEntries(
  Object.entries({ en, ar })
    .map(([language, phrases]) => [language, [
      ...phrases,
      ...records[language],
      ...connectedTools[language],
      ...supplementalInterface[language],
      ...processingPhrases[language],
      ...portalRedesign[language],
    ]]),
);

Object.entries(UI_PHRASEBOOKS).forEach(([language, phrases]) => {
  if (phrases.length !== UI_PHRASEBOOKS.en.length) {
    throw new Error(`Incomplete ${language} interface phrasebook: ${phrases.length}/${UI_PHRASEBOOKS.en.length}`);
  }
});
